#!/usr/bin/env perl
use strict;
use warnings;
use utf8;
use FindBin;
use Cwd qw(abs_path);
use File::Spec;
use JSON::PP;

# ==============================================================================
# deploy-github.pl
# 
# Creates a GitHub Release for SlackHacks using the GitHub REST API and uploads
# the packaged zip artifact generated by build.sh.
#
# Prerequisites:
# 1. Proton Pass CLI (pass-cli) installed and authenticated.
# 2. GitHub Personal Access Token (classic or fine-grained with contents:write)
#    stored in Proton Pass.
# ==============================================================================

my $script_dir = $FindBin::Bin;
chdir($script_dir) or die "Cannot change directory to $script_dir: $!\n";

# ------------------------------------------------------------------------------
# Configurable Variables & Settings (Environment variables take precedence)
# ------------------------------------------------------------------------------
my $github_repo            = $ENV{GITHUB_REPO}            || "Slackwise/SlackHacks";
my $target_commitish       = $ENV{TARGET_COMMITISH}       || "main";
my $is_draft               = ($ENV{IS_DRAFT} && $ENV{IS_DRAFT} =~ /^(1|true|yes)$/i) ? JSON::PP::true : JSON::PP::false;
my $is_prerelease          = ($ENV{IS_PRERELEASE} && $ENV{IS_PRERELEASE} =~ /^(1|true|yes)$/i) ? JSON::PP::true : JSON::PP::false;
my $generate_release_notes = (!defined $ENV{GENERATE_RELEASE_NOTES} || $ENV{GENERATE_RELEASE_NOTES} =~ /^(1|true|yes)$/i) ? JSON::PP::true : JSON::PP::false;
my $changelog_file         = $ENV{CHANGELOG_FILE}         || "";

# Proton Pass CLI settings
my $proton_pass_item       = $ENV{PROTON_PASS_ITEM}       || "GitHub";
my $proton_pass_vault      = $ENV{PROTON_PASS_VAULT}      || "";
my $proton_pass_attribute  = $ENV{PROTON_PASS_ATTRIBUTE}  || "password";
my $proton_pass_cli_bin    = $ENV{PROTON_PASS_CLI_BIN}    || "pass-cli";

# Dry run flag: --dry-run
my $dry_run = 0;
for my $arg (@ARGV) {
    if ($arg eq '--dry-run' || $arg eq '-n') {
        $dry_run = 1;
    }
}

# ------------------------------------------------------------------------------
# Helper: Fetch secret from Proton Pass CLI
# ------------------------------------------------------------------------------
sub fetch_secret_from_proton_pass {
    my ($item, $vault, $attr) = @_;

    if ($ENV{GITHUB_TOKEN} && $ENV{GITHUB_TOKEN} =~ /\S/) {
        return $ENV{GITHUB_TOKEN};
    }

    my @cmd = ($proton_pass_cli_bin, "item", "view", "--item-title", $item, "--field", $attr);
    if ($vault ne "") {
        push @cmd, "--vault-name", $vault;
    }

    open my $pipe, "-|", @cmd or do {
        warn "Error: Failed to execute '$proton_pass_cli_bin': $!\n";
        warn "Please ensure the Proton Pass CLI is installed in PATH, or set GITHUB_TOKEN.\n";
        return undef;
    };
    my $secret = do { local $/; <$pipe> };
    close $pipe;

    if (defined $secret) {
        $secret =~ s/^\s+|\s+$//g;
    }

    if (!defined $secret || $secret eq "") {
        warn "Error: Could not retrieve secret for item '$item' from Proton Pass.\n";
        return undef;
    }

    return $secret;
}

# ------------------------------------------------------------------------------
# Step 1: Extract Version from SlackHacks.toc & Check Build Artifact
# ------------------------------------------------------------------------------
my $toc_file = "SlackHacks.toc";
die "Error: $toc_file not found in $script_dir\n" unless -f $toc_file;

open my $fh, "<:encoding(UTF-8)", $toc_file or die "Cannot open $toc_file: $!\n";
my $version;
while (my $line = <$fh>) {
    if ($line =~ /^\s*##\s*Version:\s*(.+)$/i) {
        $version = $1;
        $version =~ s/^\s+|\s+$//g;
        $version =~ s/^v//i; # strip leading v if present
        last;
    }
}
close $fh;

die "Error: Could not extract version from $toc_file\n" unless defined $version && length($version);

my $tag_name      = "v$version";
my $release_title = "SlackHacks v$version";
my $zip_name      = "SlackHacks-v$version.zip";
my $zip_path      = File::Spec->catfile("dist", $zip_name);

if (!-f $zip_path) {
    print "Zip archive '$zip_path' not found. Running build.sh first...\n";
    my $build_status = system("bash", "build.sh");
    if ($build_status != 0) {
        die "Error: build.sh failed with exit code " . ($build_status >> 8) . "\n";
    }
}

die "Error: Build output '$zip_path' not found after build.\n" unless -f $zip_path;
print "Found release archive: $zip_path\n";

# ------------------------------------------------------------------------------
# Step 2: Retrieve GitHub Token from Proton Pass
# ------------------------------------------------------------------------------
my $github_token;
if ($dry_run) {
    print "[Dry Run] Skipping Proton Pass token retrieval.\n";
    $github_token = "DRY_RUN_TOKEN";
} else {
    print "Fetching GitHub Token from Proton Pass...\n";
    $github_token = fetch_secret_from_proton_pass($proton_pass_item, $proton_pass_vault, $proton_pass_attribute);
    die "Failed to retrieve GitHub Token.\n" unless defined $github_token;
    print "Successfully retrieved GitHub Token.\n";
}

# ------------------------------------------------------------------------------
# Step 3: Prepare Release Notes / Body
# ------------------------------------------------------------------------------
my $release_body = "";
if ($changelog_file eq "") {
    my $default_changelog = File::Spec->catfile("changelog", "changelog-v$version.md");
    if (-f $default_changelog) {
        $changelog_file = $default_changelog;
    }
}

if ($changelog_file ne "" && -f $changelog_file) {
    open my $cfh, "<:encoding(UTF-8)", $changelog_file or warn "Cannot open changelog file '$changelog_file': $!\n";
    if ($cfh) {
        $release_body = do { local $/; <$cfh> };
        close $cfh;
    }
}

# ------------------------------------------------------------------------------
# Step 4: Create GitHub Release
# ------------------------------------------------------------------------------
my $json_codec = JSON::PP->new->utf8->canonical;

my $payload = {
    tag_name               => $tag_name,
    target_commitish       => $target_commitish,
    name                   => $release_title,
    body                   => $release_body,
    draft                  => $is_draft,
    prerelease             => $is_prerelease,
    generate_release_notes => $generate_release_notes,
};

my $payload_json = $json_codec->encode($payload);
my $api_url = "https://api.github.com/repos/$github_repo/releases";

print "=== GitHub Release Summary ===\n";
print "Repository:          $github_repo\n";
print "Tag Name:            $tag_name\n";
print "Target Commit/Branch:$target_commitish\n";
print "Release Title:       $release_title\n";
print "Draft:               " . ($is_draft ? "true" : "false") . "\n";
print "Prerelease:          " . ($is_prerelease ? "true" : "false") . "\n";
print "Auto Release Notes:  " . ($generate_release_notes ? "true" : "false") . "\n";
print "Artifact:            $zip_path\n";
print "==============================\n";

if ($dry_run) {
    print "[Dry Run] Release simulation complete. No GitHub release created.\n";
    exit 0;
}

print "Creating GitHub Release...\n";
my @create_cmd = (
    "curl", "-s", "-S",
    "-w", "\nHTTP_STATUS:%{http_code}",
    "-X", "POST",
    "-H", "Accept: application/vnd.github+json",
    "-H", "Authorization: Bearer $github_token",
    "-H", "X-GitHub-Api-Version: 2022-11-28",
    "-d", $payload_json,
    $api_url
);

open my $create_pipe, "-|", @create_cmd or die "Failed to execute curl: $!\n";
my $create_resp = do { local $/; <$create_pipe> };
close $create_pipe;

my $http_status = 0;
if ($create_resp =~ /HTTP_STATUS:(\d+)/) {
    $http_status = int($1);
    $create_resp =~ s/\n?HTTP_STATUS:\d+//;
}

if ($http_status < 200 || $http_status >= 300) {
    die "Error: Failed to create GitHub Release (HTTP $http_status).\nResponse: $create_resp\n";
}

my $release_data = eval { $json_codec->decode($create_resp) };
if (!$release_data || !$release_data->{id}) {
    die "Error: Could not parse release response from GitHub.\nResponse: $create_resp\n";
}

my $release_id  = $release_data->{id};
my $release_url = $release_data->{html_url} || "";

print "Created release successfully (ID: $release_id): $release_url\n";

# ------------------------------------------------------------------------------
# Step 5: Upload Zip Asset
# ------------------------------------------------------------------------------
my $upload_url = "https://uploads.github.com/repos/$github_repo/releases/$release_id/assets?name=$zip_name";

print "Uploading asset $zip_name to GitHub release...\n";
my @upload_cmd = (
    "curl", "-s", "-S",
    "-w", "\nHTTP_STATUS:%{http_code}",
    "-X", "POST",
    "-H", "Accept: application/vnd.github+json",
    "-H", "Authorization: Bearer $github_token",
    "-H", "Content-Type: application/zip",
    "-H", "X-GitHub-Api-Version: 2022-11-28",
    "--data-binary", "\@$zip_path",
    $upload_url
);

open my $upload_pipe, "-|", @upload_cmd or die "Failed to execute curl: $!\n";
my $upload_resp = do { local $/; <$upload_pipe> };
close $upload_pipe;

my $upload_http_status = 0;
if ($upload_resp =~ /HTTP_STATUS:(\d+)/) {
    $upload_http_status = int($1);
    $upload_resp =~ s/\n?HTTP_STATUS:\d+//;
}

if ($upload_http_status >= 200 && $upload_http_status < 300) {
    print "Asset uploaded successfully (HTTP $upload_http_status)!\n";
    print "Release URL: $release_url\n";
} else {
    die "Error: Asset upload failed with HTTP status $upload_http_status.\nResponse: $upload_resp\n";
}
